#[derive(Debug, PartialEq, Eq, Clone, Copy)]
enum RightHead {
    H,
    A,
    B,
}

impl HigherState {
    fn try_to_right_head(&self) -> Option<RightHead> {
        match &self {
            HigherState::Right => Some(RightHead::H),
            HigherState::RightA => Some(RightHead::A),
            HigherState::RightB => Some(RightHead::B),
            _ => None,
        }
    }
}

impl RightHead {
    fn to_higher_state(&self) -> HigherState {
        match &self {
            RightHead::H => HigherState::Right,
            RightHead::A => HigherState::RightA,
            RightHead::B => HigherState::RightB,
        }
    }
}

impl fmt::Display for RightHead {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self {
            RightHead::H => write!(f, "h"),
            RightHead::A => write!(f, "a"),
            RightHead::B => write!(f, "b"),
        }
    }
}

#[derive(Debug, PartialEq, Eq)]
struct RightHeadSeq(Vec<(RightHead, usize)>);

impl RightHeadSeq {
    fn new() -> Self {
        Self(Vec::new())
    }

    fn from_str(s: &str) -> Option<Self> {
        let mut out = Vec::new();
        for p in s.split(" ") {
            let (symb_str, exp) = if p.contains("^") {
                let (symb_str, exp_str) = p.split_once("^").unwrap();
                (symb_str, exp_str.parse::<usize>().unwrap())
            } else {
                (p, 1)
            };

            let symb = match symb_str {
                "h" => RightHead::H,
                "a" => RightHead::A,
                "b" => RightHead::B,
                _ => return None,
            };
            out.push((symb, exp));
        }
        out.reverse();
        Some(RightHeadSeq(out))
    }

    fn pop(&mut self) -> Option<RightHead> {
        loop {
            if let Some((rhead0, n0)) = self.0.first() {
                if *n0 == 0 {
                    self.0.remove(0);
                    continue;
                } else {
                    let out = *rhead0;
                    if *n0 == 1 {
                        self.0.remove(0);
                    } else {
                        self.0[0] = (*rhead0, n0 - 1);
                    }
                    return Some(out);
                }
            } else {
                return None;
            }
        }
    }

    fn push_head(&mut self, rhead: RightHead) {
        if let Some((rhead0, n0)) = self.0.last_mut()
            && *rhead0 == rhead
        {
            *n0 += 1;
        } else {
            self.0.push((rhead, 1));
        }
    }

    fn append_seq(&mut self, seq: &RightHeadSeq) {
        if let Some((rhead0, n0)) = self.0.last_mut()
            && let Some((rhead1, n1)) = seq.0.first()
            && rhead0 == rhead1
        {
            *n0 += n1;
            self.0.extend_from_slice(&seq.0[1..]);
        } else {
            self.0.extend_from_slice(seq.0.as_slice());
        }
    }
}

impl fmt::Display for RightHeadSeq {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut iter = self.0.iter().rev();
        if let Some((rhead, n)) = iter.next() {
            if *n == 1 {
                write!(f, "{}", rhead)?;
            } else {
                write!(f, "{}^{}", rhead, n)?;
            }
        }
        while let Some((rhead, n)) = iter.next() {
            write!(f, " ")?;
            if *n == 1 {
                write!(f, "{}", rhead)?;
            } else {
                write!(f, "{}^{}", rhead, n)?;
            }
        }
        Ok(())
    }
}

