fn check_right_long_rule(right_head_str: &str, rtape_s: &str) {
    let mut rheads = RightHeadSeq::from_str(right_head_str).unwrap();
    let rtape_init = parse_right_tape(rtape_s).unwrap();

    let rhead0 = rheads.pop().unwrap();
    let mut sim = BlockSimulator::new_right_long(rhead0.to_higher_state(), rtape_init.clone());
    println!("{sim}");

    loop {
        if sim.left_tape.is_empty() && sim.state == HigherState::Left && !rheads.0.is_empty() {
            sim.state = rheads.pop().unwrap().to_higher_state();
            println!("{sim}");
        }

        let res = sim.step();
        println!("{sim}");
        if res.is_err() {
            if res == Err(SimError::LongSimCompleted) {
                assert_eq!(rheads.pop(), None);
                if let SimInfo::RightLong { right_heads } = sim.sim_info {
                    println!(
                        "{} {}-> {}{} ({})",
                        right_head_str,
                        DisplayRTape(&rtape_init),
                        DisplayRTape(&sim.right_tape),
                        right_heads,
                        sim.base_steps
                    );
                } else {
                    unreachable!()
                }
            } else {
                println!("{:?}", res);
            }
            break;
        }
    }
}

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
enum RightSimHead {
    H,
    A,
    H2,
    HB,
    B,
}

impl fmt::Display for RightSimHead {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use RightSimHead::*;
        match &self {
            H => write!(f, "h"),
            A => write!(f, "a"),
            H2 => write!(f, "h^2"),
            HB => write!(f, "hb"),
            B => write!(f, "b"),
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum LongSymbol {
    Head(RightSimHead),
    Block(BlockSymbol),
}

impl fmt::Display for LongSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match &self {
            Self::Head(h) => write!(f, "{}", h),
            Self::Block(b) => write!(f, "{}", b),
        }
    }
}

use std::collections::VecDeque;

fn push_run_vd(tape: &mut VecDeque<LongSymbol>, run_type: RunSymbolType, nadd: Exp) {
    use BlockSymbol::*;
    if nadd > 0 {
        match tape.back_mut() {
            Some(LongSymbol::Block(Run(t, n))) if *t == run_type => *n += nadd,
            _ => tape.push_back(LongSymbol::Block(Run(run_type, nadd))),
        }
    }
}

struct LongSim {
    /// back of near_tape connects with end_tape
    near_tape: VecDeque<LongSymbol>,

    /// must not contain heads
    end_tape: Vec<BlockSymbol>,
    head_steps: u64,
    self_move_steps: u64,
}

impl fmt::Display for LongSim {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        self.head_steps.fmt(f)?;
        write!(f, ": ")?;

        const LEFT_PRINT_THRESHOLD: usize = 25;
        let l_th = LEFT_PRINT_THRESHOLD / 2;
        if self.near_tape.len() <= LEFT_PRINT_THRESHOLD {
            for symb in &self.near_tape {
                write!(f, "{} ", symb)?;
            }
        } else {
            let mut iter = self.near_tape.iter();
            for _ in 0..l_th {
                write!(f, "{} ", iter.next().unwrap())?;
            }
            write!(
                f,
                " ...{} terms... ",
                self.near_tape.len() - LEFT_PRINT_THRESHOLD
            )?;
            for i in self.near_tape.len() - l_th..self.near_tape.len() {
                write!(f, "{} ", self.near_tape.get(i).unwrap())?;
            }
        }
        write!(f, " ")?;
        const RIGHT_PRINT_THRESHOLD: usize = 30;
        let r_th = RIGHT_PRINT_THRESHOLD / 2;
        if self.end_tape.len() <= RIGHT_PRINT_THRESHOLD {
            for symb in self.end_tape.iter().rev() {
                write!(f, " {}", symb)?;
            }
        } else {
            for symb in self.end_tape[self.end_tape.len() - r_th..].iter().rev() {
                write!(f, " {}", symb)?;
            }
            write!(
                f,
                " ...{} terms... ",
                self.end_tape.len() - RIGHT_PRINT_THRESHOLD
            )?;
            for symb in self.end_tape[..r_th].iter().rev() {
                write!(f, " {}", symb)?;
            }
        }
        Ok(())
    }
}

macro_rules! x {
    () => {
        BlockSymbol::Run(RunSymbolType::X, 1)
    };
    ($v:tt) => {
        BlockSymbol::Run(RunSymbolType::X, $v)
    };
    ($start:literal ..) => {
        BlockSymbol::Run(RunSymbolType::X, $start..)
    };
}

macro_rules! push_near {
    ($self_ident:ident) => {};
    ($self_ident:ident T $($rest:tt)*) => {
        $self_ident.push_near_block(BlockSymbol::T);
        push_near!($self_ident $($rest)*);
    };
    ($self_ident:ident Q $($rest:tt)*) => {
        $self_ident.push_near_block(BlockSymbol::Q);
        push_near!($self_ident $($rest)*);
    };
    ($self_ident:ident a $($rest:tt)*) => {
        $self_ident.push_near_head(RightSimHead::A);
        push_near!($self_ident $($rest)*);
    };
    ($self_ident:ident hb $($rest:tt)*) => {
        $self_ident.push_near_head(RightSimHead::HB);
        push_near!($self_ident $($rest)*);
    };
    ($self_ident:ident h^2 $($rest:tt)*) => {
        $self_ident.push_near_head(RightSimHead::H2);
        push_near!($self_ident $($rest)*);
    };
    ($self_ident:ident $n:literal $($rest:tt)*) => {
        $self_ident.push_near_block(x!($n));
        push_near!($self_ident $($rest)*);
    };
}

impl LongSim {
    fn new(near_tape: VecDeque<LongSymbol>, end_tape: Vec<BlockSymbol>) -> Self {
        Self {
            near_tape,
            end_tape,
            head_steps: 0,
            self_move_steps: 0,
        }
    }

    fn push_near_block(&mut self, b: BlockSymbol) {
        self.near_tape.push_back(LongSymbol::Block(b));
    }

    fn push_near_head(&mut self, h: RightSimHead) {
        self.near_tape.push_back(LongSymbol::Head(h));
    }

    fn push_end_XQ(&mut self, n: Exp) {
        use BlockSymbol::*;
        use RunSymbolType::*;
        if self.end_tape.last() == Some(&T) {
            // X^n Q T = X^n X = X^n+1
            self.end_tape.pop();
            add_or_merge_run(&mut self.end_tape, X, n + 1);
        } else {
            self.end_tape.extend_from_slice(&[Q, Run(X, n)]);
        }
    }

    fn step(&mut self) -> bool {
        use BlockSymbol::*;
        use RightSimHead::*;
        use RunSymbolType::*;

        match self.near_tape.back() {
            None => unimplemented!(),
            Some(LongSymbol::Head(h0)) => {
                // get and pop the current head and any X^n run it is facing
                let h = *h0;
                self.near_tape.pop_back();
                let x_exp = if let Some(Run(X, n0)) = self.end_tape.last() {
                    let n = *n0;
                    self.end_tape.pop();
                    n
                } else {
                    0
                };

                match (h, x_exp, self.end_tape.as_slice()) {
                    // h Q X -> X T a
                    (H, _, [.., x!(_), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 1);
                        push_near!(self T a);
                        self.end_tape.pop();
                        decrement_run(&mut self.end_tape, X);
                    }
                    // a 3 Q 2 -> 1 T 1 h b (53)
                    (A, 3.., [.., x!(2..), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp - 2);
                        push_near!(self T 1 hb);
                        self.end_tape.pop();
                        decrease_run_by(&mut self.end_tape, X, 2);
                    }
                    // a 3 Q 1 Q 1 -> 1 T 1 Q 1 T 1 Q  (84)
                    (A, 3.., [.., x!(_), Q, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                        self.push_end_XQ(1);
                        self.end_tape
                            .extend_from_slice(&[T, x!(), Q, x!(), T, x!()]);
                    }
                    // a 3 Q 1 T -> 1 T 1 Q 2 a (66) revised to
                    // a 3 Q 1 T -> 1 T 1 Q a 2
                    (A, 3.., [.., T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp - 2);
                        push_near!(self T 1 Q a);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                        add_or_merge_run(&mut self.end_tape, X, 2);
                    }
                    // a X T -> X T h^2
                    (A, 1.., [.., T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self T h^2);
                        self.end_tape.pop();
                    }
                    // a R1 -> 1 T 2 R1  (34)
                    (A, _, [R1]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        self.end_tape.extend_from_slice(&[x!(2), T, x!()]);
                    }
                    // h^2 T 1 T 1 Q 2 T -> 3 h b a h^2 (163) revised to
                    // h^2 T 1 T 1 Q 2 T -> 2 h b a 1 h^2
                    (H2, _, [.., T, x!(2), Q, x!(), T, x!(), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 2);
                        push_near!(self hb a 1 h^2);
                        for _ in 0..7 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 1 T 1 T -> 1 T 1 Q a h^2 (46)
                    (H2, 1.., [.., T, x!(), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self T 1 Q a h^2);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 1 T 1 Q 1 -> 1 T 2 T  (38)
                    (H2, 1.., [.., x!(_), Q, x!(), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                        self.end_tape.extend_from_slice(&[T, x!(2), T, x!()]);
                    }
                    // h^2 1 T 2 T T 1 Q 1 -> 1 T 3 Q 2 a h^2 (188) revised to
                    // h^2 1 T 2 T T 1 Q 1 -> 1 T 3 Q a 2 h^2
                    (H2, 1.., [.., x!(_), Q, x!(), T, T, x!(2), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self T 3 Q a 2 h^2);
                        for _ in 0..6 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 T 2 Q 1 -> 1 b (11)
                    (H2, _, [.., Run(X, _), Q, Run(X, 2), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 1);
                        self.push_near_head(B);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 1 T 3 Q 2 Q 1 T -> 6 h b a (311), revised to
                    // h^2 1 T 3 Q 2 Q 1 T -> 3 h b a 3
                    (H2, 1.., [.., T, Run(X, 1), Q, Run(X, 2), Q, Run(X, 3), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 2);
                        push_near!(self hb a);
                        for _ in 0..7 {
                            self.end_tape.pop();
                        }
                        add_or_merge_run(&mut self.end_tape, X, 3);
                    }
                    // h^2 T 3 Q 2 T -> 2 Q 1 a h b a (171), revised to
                    // h^2 T 3 Q 2 T -> 2 Q a 1 h b a
                    (H2, _, [.., T, x!(2), Q, x!(3), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 2);
                        push_near!(self Q a 1 hb a);
                        for _ in 0..5 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 1 T 3 Q 2 -> 1 T 1 Q 1 a h b (89), revised to
                    // h^2 1 T 3 Q 2 -> 1 T 1 Q a 1 h b
                    (H2, 1.., [.., Run(X, 2..), Q, Run(X, 3), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self T 1 Q a 1 hb);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 2);
                    }
                    // h^2 1 T 3 Q 1 Q 3 -> 1 T 2 Q 1 T 1 h b (203)
                    (H2, 1.., [.., x!(3..), Q, x!(), Q, x!(3), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self T 2 Q 1 T 1 hb);
                        for _ in 0..5 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 T X -> X T a
                    (H2, _, [.., Run(X, _), T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 1);
                        push_near!(self T a);
                        self.end_tape.pop();
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 T T 1 Q 1 T -> 2 T 1 Q a h^2 (46)
                    (H2, _, [.., T, x!(), Q, x!(), T, T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 2);
                        push_near!(self T 1 Q a h^2);
                        for _ in 0..6 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 T T -> 1 h (6)
                    (H2, _, [.., T, T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 1);
                        self.push_near_head(H);
                        self.end_tape.pop();
                        self.end_tape.pop();
                    }
                    // h^2 Q 1 T 2 Q 1 T 3 Q 3 T -> 7 h b a h^3 b a h^2 (696) revised to
                    // h^2 Q 1 T 2 Q 1 T 3 Q 3 T -> 5 h b a 1 h^2 1 h b a h^2
                    (H2, _, [.., T, x!(3), Q, x!(3), T, x!(), Q, x!(2), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 5);
                        push_near!(self hb a 1 h^2 1 hb a h^2);
                        for _ in 0..11 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 Q 1 T 2 Q 1 T 3 Q 3 -> 5 Q 1 a h b a^2 h b a (504) revised to
                    // h^2 Q 1 T 2 Q 1 T 3 Q 3 -> 5 Q a 1 h b a^2 h b a
                    (H2, _, [.., x!(3..), Q, x!(3), T, x!(), Q, x!(2), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 5);
                        push_near!(self Q a 1 hb a a hb a);
                        for _ in 0..9 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 Q 1 T 2 Q 1 T 3 Q 1 T 3 -> 4 T 2 T 1 Q 1 Q 1 a h^3 b a h^2 (599), revised to
                    // h^2 Q 1 T 2 Q 1 T 3 Q 1 T 3 -> 4 T 2 T 1 Q 1 Q a h^2 1 h b a h^2
                    (
                        H2,
                        _,
                        [
                            ..,
                            x!(3..),
                            T,
                            x!(),
                            Q,
                            x!(3),
                            T,
                            x!(),
                            Q,
                            x!(2),
                            T,
                            x!(),
                            Q,
                        ],
                    ) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 4);
                        push_near!(self T 2 T 1 Q 1 Q a h^2 1 hb a h^2);
                        for _ in 0..11 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 Q 1 T 2 Q 1 T 3 -> 3 T 1 Q 1 a h^3 b a h^2 (347) revised to
                    // h^2 Q 1 T 2 Q 1 T 3 -> 3 T 1 Q a h^2 1 h b a h^2
                    (H2, _, [.., x!(3..), T, x!(), Q, x!(2), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 3);
                        push_near!(self T 1 Q a h^2 1 hb a h^2);
                        for _ in 0..7 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 Q 1 T 1 Q 4 T 1 Q 3 -> 2 T 1 Q 1 T 1 h b a^2 h b a (534)
                    (H2, _, [.., x!(3..), Q, x!(), T, x!(4), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 2);
                        push_near!(self T 1 Q 1 T 1 hb a a hb a);
                        for _ in 0..9 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 Q 1 T 1 Q 4 T 1 Q 1 T 1 Q 3 T -> 2 T 3 T 1 a^2 h b a h^3 b a^3 h b a h^2 (1027) revised to
                    // h^2 Q 1 T 1 Q 4 T 1 Q 1 T 1 Q 3 T -> 2 T 3 T a^2 h b a h^2 1 h b a^3 h b a h^2
                    (
                        H2,
                        _,
                        [
                            ..,
                            T,
                            x!(3),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                            x!(),
                            T,
                            x!(4),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                        ],
                    ) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 2);
                        push_near!(self T 3 T a a hb a h^2 1 hb a a a hb a h^2);
                        for _ in 0..15 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 Q 1 T 1 Q 4 T -> 2 T 1 Q 1 a h^3 b a h^2 (317) revised to
                    // h^2 Q 1 T 1 Q 4 T -> 2 T 1 Q a 1 h^3 b a h^2
                    (H2, _, [.., T, x!(4), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 2);
                        push_near!(self T 1 Q a 1 h^2 hb a h^2);
                        for _ in 0..7 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 Q 1 T 1 Q 3 T 2 Q 1 T 3 Q 2 T -> 4 Q 2 Q 1 T 1 Q 1 a h^3 b a h b a h^2 (1246) revised to
                    // h^2 Q 1 T 1 Q 3 T 2 Q 1 T 3 Q 2 T -> 4 Q 2 Q 1 T 1 Q a h^3 b a 1 h b a h^2
                    (
                        H2,
                        _,
                        [
                            ..,
                            T,
                            x!(2),
                            Q,
                            x!(3),
                            T,
                            x!(),
                            Q,
                            x!(2),
                            T,
                            x!(3),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                        ],
                    ) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 4);
                        push_near!(self Q 2 Q 1 T 1 Q a h^2 hb a 1 hb a h^2);
                        for _ in 0..15 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 1 Q 1 T 1 Q 3 T 2 Q 3 -> 1 Q 2 T 1 Q 2 a h^3 b a h b a (572) revised to
                    // h^2 1 Q 1 T 1 Q 3 T 2 Q 3 -> 1 Q 2 T 1 Q a 1 h^3 b a 1 h b a
                    (H2, 1.., [.., x!(3..), Q, x!(2), T, x!(3), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 2 T 1 Q a 1 h^2 hb a 1 hb a);
                        for _ in 0..9 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 Q 1 T 1 Q 3 T 2 Q 1 T 3 -> 4 Q 1 Q 2 a h^3 b a h b a h^2 (876) revised to
                    // h^2 Q 1 T 1 Q 3 T 2 Q 1 T 3 -> 4 Q 1 Q a h^2 1 h b a 1 h b a h^2
                    // not implemented
                    //
                    // h^2 Q 1 T 1 Q 3 T 1 Q 3 -> 4 Q 1 a^2 h b a h b a (488) revised to
                    // h^2 Q 1 T 1 Q 3 T 1 Q 3 -> 4 Q a^2 h b a 1 h b a
                    (H2, _, [.., x!(3..), Q, x!(), T, x!(3), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 4);
                        push_near!(self Q a a hb a 1 hb a);
                        for _ in 0..9 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 1 Q 1 T 1 Q 3 T 1 Q 1 T 4 Q 3 -> 1 Q 8 h b a h^3 b a h b a (1093) revised to
                    // h^2 1 Q 1 T 1 Q 3 T 1 Q 1 T 4 Q 3 -> 1 Q 5 h b a 1 h^2 1 h b a 1 h b a
                    (
                        H2,
                        1..,
                        [
                            ..,
                            x!(3..),
                            Q,
                            x!(4),
                            T,
                            x!(),
                            Q,
                            x!(),
                            T,
                            x!(3),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                        ],
                    ) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 5 hb a 1 h^2 1 hb a 1 hb a);
                        for _ in 0..13 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 1 Q 1 T 1 Q 3 T -> 1 Q 3 T a^2 h b a h^2 (261)
                    (H2, 1.., [.., T, x!(3), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 3 T a a hb a h^2);
                        for _ in 0..7 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 Q 1 T 1 Q 3 -> 3 T a^2 h b a (137)
                    (H2, _, [.., x!(3..), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 3);
                        push_near!(self T a a hb a);
                        for _ in 0..5 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 Q 1 T 1 Q 2 T -> 3 h^2 b a h^2 (173) revised to
                    // h^2 Q 1 T 1 Q 2 T -> 2 h^2 b a 1 h^2
                    (H2, _, [.., T, x!(2), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 2);
                        self.push_near_head(H);
                        push_near!(self hb a 1 h^2);
                        for _ in 0..7 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 3 Q 1 T 1 Q 1 T 1 -> 1 Q 2 Q 1 T 1 Q T 2 Q 1 T 1 Q T 1 Q a h^2 (450) revised to
                    // h^2 1 Q 1 T 1 Q 1 T 3 Q 1 T 1 Q 1 T 1 -> 1 Q 2 Q 1 T 4 Q 1 T 3 Q a h^2 (450)
                    (
                        H2,
                        1..,
                        [
                            ..,
                            x!(_),
                            T,
                            x!(),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                            x!(3),
                            T,
                            x!(),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                        ],
                    ) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 2 Q 1 T 4 Q 1 T 3 Q a h^2);
                        for _ in 0..15 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 3 Q 1 T 1 -> 1 Q 2 Q 1 T 1 Q T 1 Q 1 T 1 Q a h^2 (310) revised to
                    // h^2 1 Q 1 T 1 Q 1 T 3 Q 1 T 1 -> 1 Q 2 Q 1 T 3 Q 1 T 1 Q a h^2 (310)
                    (H2, 1.., [.., x!(_), T, x!(), Q, x!(3), T, x!(), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 2 Q 1 T 3 Q 1 T 1 Q a h^2);
                        for _ in 0..11 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 2 Q 3 T -> 1 Q 2 Q 1 T 1 Q T 2 Q 2 a h^2 (304) revised to
                    // h^2 1 Q 1 T 1 Q 1 T 2 Q 3 T -> 1 Q 2 Q 1 T 4 Q a 2 h^2
                    (H2, 1.., [.., T, x!(3), Q, x!(2), T, x!(), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 2 Q 1 T 4 Q a 2 h^2);
                        for _ in 0..11 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 2 Q 3 -> 1 Q 2 Q 1 T 1 Q T 1 h b a (247) revised to
                    // h^2 1 Q 1 T 1 Q 1 T 2 Q 3 -> 1 Q 2 Q 1 T 3 h b a (247)
                    (H2, 1.., [.., x!(3..), Q, x!(2), T, x!(), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 2 Q 1 T 3 hb a);
                        for _ in 0..9 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 2 Q 2 T -> 1 Q 2 Q 1 T 1 Q T 1 Q 2 a h^2 (266) revised to
                    // h^2 1 Q 1 T 1 Q 1 T 2 Q 2 T -> 1 Q 2 Q 1 T 3 Q a 2 h^2
                    (H2, 1.., [.., T, x!(2), Q, x!(2), T, x!(), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 2 Q 1 T 3 Q a 2 h^2);
                        for _ in 0..11 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 1 Q 3 T 2 Q 3 -> 1 Q 3 Q 1 T 1 h b a h^3 b a h b a (739)
                    (
                        H2,
                        1..,
                        [
                            ..,
                            x!(3..),
                            Q,
                            x!(2),
                            T,
                            x!(3),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                        ],
                    ) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 3 Q 1 T 1 hb a h^2 hb a hb a);
                        for _ in 0..13 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 1 Q 3 T -> 1 Q 4 Q 2 a^3 h b a h^2 (417) revised to
                    // h^2 1 Q 1 T 1 Q 1 T 1 Q 3 T -> 1 Q 4 Q a 2 a^2 h b a h^2
                    (H2, 1.., [.., T, x!(3), Q, x!(), T, x!(), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 4 Q a 2 a a hb a h^2);
                        for _ in 0..11 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 1 Q 3 -> 1 Q 1 Q 4 T h^2 a^2 h b a (217)
                    (H2, 1.., [.., x!(3..), Q, x!(), T, x!(), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 1 Q 4 T h^2 a a hb a);
                        for _ in 0..9 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 1 Q 1 T 2 Q 3 -> 1 Q 3 Q 1 T 1 Q T 1 Q T 1 h b a (387) revised to
                    // h^2 1 Q 1 T 1 Q 1 T 1 Q 1 T 2 Q 3 -> 1 Q 3 Q 1 T 5 h b a
                    (
                        H2,
                        1..,
                        [
                            ..,
                            x!(3..),
                            Q,
                            x!(2),
                            T,
                            x!(),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                            x!(),
                            T,
                            x!(),
                            Q,
                        ],
                    ) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 3 Q 1 T 5 hb a);
                        for _ in 0..13 {
                            self.end_tape.pop();
                        }
                        decrease_run_by(&mut self.end_tape, X, 3);
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 1 Q 1 T 1 -> 1 Q 3 Q 1 T 1 Q T 1 Q a h^2 (304) revised to
                    // h^2 1 Q 1 T 1 Q 1 T 1 Q 1 T 1 -> 1 Q 3 Q 1 T 3 Q a h^2
                    (H2, 1.., [.., x!(_), T, x!(), Q, x!(), T, x!(), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 3 Q 1 T 3 Q a h^2);
                        for _ in 0..11 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 1 Q 1 T 1 Q 1 T 1 -> 1 Q 2 Q 1 T 1 Q a h^2 (164)
                    (H2, 1.., [.., x!(_), T, x!(), Q, x!(), T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 2 Q 1 T 1 Q a h^2);
                        for _ in 0..7 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 1 Q 1 T -> 1 Q 1 Q a h^2 (46)
                    (H2, 1.., [.., T, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        push_near!(self Q 1 Q a h^2);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                    }
                    // h^2 Q 2 Q 1 -> 1 h b (13)
                    (H2, _, [.., x!(_), Q, x!(2), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 1);
                        self.push_near_head(HB);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 1 Q 1 Q 1 -> 1 Q 2 T  (38)
                    (H2, 1.., [.., x!(_), Q, x!(), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        for _ in 0..3 {
                            self.end_tape.pop();
                        }
                        decrement_run(&mut self.end_tape, X);
                        self.end_tape.extend_from_slice(&[T, x!(2), Q, x!()]);
                    }
                    // h^2 Q X -> X Q a
                    (H2, _, [.., Run(X, _), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 1);
                        self.push_near_block(Q);
                        self.push_near_head(A);
                        self.end_tape.pop();
                        decrement_run(&mut self.end_tape, X);
                    }
                    // h^2 R1 -> 4 R1  (36)
                    (H2, _, [R1]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        self.end_tape.push(Run(X, 4));
                    }
                    // h b T -> 1 Q 2 a (47) revised to
                    // h b T -> 1 Q a 2
                    (HB, _, [.., T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 1);
                        self.push_near_block(Q);
                        // self.push_near_block(Run(X, 2));
                        self.push_near_head(A);
                        self.end_tape.pop();
                        add_or_merge_run(&mut self.end_tape, X, 2);
                    }
                    // h b Q 1 -> 1 Q 1 T 1 Q  (65)
                    (HB, _, [.., Run(X, _), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        self.end_tape.pop();
                        decrement_run(&mut self.end_tape, X);
                        self.push_end_XQ(1);
                        self.end_tape
                            .extend_from_slice(&[T, Run(X, 1), Q, Run(X, 1)]);
                    }
                    // b T -> 1 T 2 a (41) revised to
                    // b T -> 1 T a 2
                    (B, _, [.., T]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp + 1);
                        self.push_near_block(T);
                        self.push_near_head(A);
                        self.end_tape.pop();
                        add_or_merge_run(&mut self.end_tape, X, 2);
                    }
                    // b Q 1 -> 1 T 1 T 1 Q  (59)
                    (B, _, [.., x!(_), Q]) => {
                        push_run_vd(&mut self.near_tape, X, x_exp);
                        self.end_tape.pop();
                        decrement_run(&mut self.end_tape, X);
                        self.push_end_XQ(1);
                        self.end_tape.extend_from_slice(&[T, x!(), T, x!()]);
                    }
                    _ => unimplemented!(),
                }

                self.head_steps += 1;
                true
            }
            Some(LongSymbol::Block(b)) => {
                match *b {
                    Run(t, n) => {
                        add_or_merge_run(&mut self.end_tape, t, n);
                    }
                    L => unreachable!(),
                    other => self.end_tape.push(other),
                }
                self.near_tape.pop_back();
                self.self_move_steps += 1;
                false
            }
        }
    }
}

fn draw_long_sim(sim: &LongSim, nr: usize, nc: usize, out_fname: String) {
    #[derive(Default, Clone)]
    struct Pixel {
        r: u8,
        g: u8,
        b: u8,
    }

    impl Pixel {
        const fn new(r: u8, g: u8, b: u8) -> Self {
            Self { r, g, b }
        }

        fn grey(v: u8) -> Self {
            Self { r: v, g: v, b: v }
        }
    }

    const C_T: Pixel = Pixel::new(69, 125, 253);
    const C_Q: Pixel = Pixel::new(0, 129, 88);
    const C_R1: Pixel = Pixel::new(160, 198, 95);
    const GREYS: [u8; 6] = [255, 205, 172, 135, 96, 38];

    const C_A: Pixel = Pixel::new(255, 6, 22);
    const C_H2: Pixel = Pixel::new(250, 110, 0);
    const C_H: Pixel = Pixel::new(254, 216, 24);
    const C_HB: Pixel = Pixel::new(238, 85, 253);
    const C_B: Pixel = Pixel::new(203, 43, 253);

    fn block_to_color(b: &BlockSymbol) -> Pixel {
        use BlockSymbol::*;
        match *b {
            L | R1 | R => C_R1,
            T => C_T,
            Q => C_Q,
            Run(RunSymbolType::X, n @ 1..=5) => Pixel::grey(GREYS[n as usize - 1]),
            Run(RunSymbolType::X, 0) => unreachable!(),
            Run(RunSymbolType::X, 6..) => Pixel::grey(GREYS[5]),
        }
    }

    fn head_to_color(h: &RightSimHead) -> Pixel {
        use RightSimHead::*;
        match *h {
            A => C_A,
            H2 => C_H2,
            H => C_H,
            HB => C_HB,
            B => C_B,
        }
    }

    let mut data: Vec<Vec<Pixel>> = vec![vec![Pixel::default(); nc]; nr];
    let mut idx = 0;

    for t in &sim.near_tape {
        let r = idx / nc;
        let c = idx % nc;
        if r < nr {
            data[r][c] = match t {
                LongSymbol::Block(b) => block_to_color(b),
                LongSymbol::Head(h) => head_to_color(h),
            };
        }
        idx += 1;
    }

    if !(sim.near_tape.back() == Some(&LongSymbol::Head(RightSimHead::HB))
        && matches!(
            sim.end_tape.last(),
            Some(&BlockSymbol::Run(RunSymbolType::X, _))
        ))
    // && sim.end_tape.len() % 2 == 0
    {
        idx += 1;
    }

    for b in sim.end_tape.iter().rev() {
        let r = idx / nc;
        let c = idx % nc;
        if r < nr {
            data[r][c] = block_to_color(b);
        }
        idx += 1;
    }

    let data_flat: Vec<u8> = data
        .into_iter()
        .flatten()
        .map(|p| [p.r, p.g, p.b, 255])
        .flatten()
        .collect();

    use std::fs::File;
    use std::io::BufWriter;
    let file = File::create(out_fname).unwrap();
    let w = &mut BufWriter::new(file);
    let mut encoder = png::Encoder::new(w, nc as u32, nr as u32);
    encoder.set_color(png::ColorType::Rgba);
    encoder.set_depth(png::BitDepth::Eight);
    let mut writer = encoder.write_header().unwrap();
    writer.write_image_data(&data_flat).unwrap();
}

fn process_right(draw: bool) {
    // let r_def = include_str!("../definitions/bb6_right_merge/right_h_43812085.txt").trim();
    let r_def = include_str!("../definitions/bb6_right_merge/right_h_43873633.txt").trim();

    let rtape_process = parse_right_tape(r_def).unwrap();

    let mut sim = LongSim::new(
        VecDeque::from([LongSymbol::Head(RightSimHead::H)]),
        rtape_process.clone(),
    );

    println!("{sim}");

    let mut img_idx: u32 = 0;
    if draw {
        draw_long_sim(
            &sim,
            50,
            70,
            format!("tmp_out/f{img_idx:05}.png").to_owned(),
        );
        img_idx += 1;
    }

    let mut prev_n_head_terms: usize = 0;
    loop {
        let is_step = sim.step();
        if true
        // is_step
        //&& sim.head_steps > 8400 && sim.head_steps < 8500
        // sim.head_steps >= 50000
        {
            if draw {
                draw_long_sim(
                    &sim,
                    50,
                    70,
                    format!("tmp_out/f{img_idx:05}.png").to_owned(),
                );
                img_idx += 1;
            }

            if sim.head_steps > 152000 {
                // if true {
                // if ((sim.near_tape.len() as i32) - 2554).abs() < 10 {
                println!("{sim}");

                let n_head_terms = sim
                    .near_tape
                    .iter()
                    .filter(|t| matches!(t, LongSymbol::Head(_)))
                    .count();

                // if true {
                if false {
                    println!(
                        "near tape size {} w/ {} heads, end tape size {}, total {}",
                        sim.near_tape.len(),
                        n_head_terms,
                        sim.end_tape.len(),
                        sim.near_tape.len() + sim.end_tape.len()
                    );
                }
            }

            // if n_head_terms != prev_n_head_terms {
            //     print!("{n_head_terms},");
            //     // print!("{},", n_head_terms as isize - prev_n_head_terms as isize);
            //     prev_n_head_terms = n_head_terms;
            // }
        }
    }
}

